def tally(words):
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return counts

def any_dirty(files):
    dirty = False
    for f in files:
        if f.modified:
            dirty = True
    return dirty

def flags(self):
    mask = 0
    if self.readable:
        mask |= READ
    if self.writable:
        mask |= WRITE
    return mask

def pairs(items):
    out = []
    for i, item in enumerate(items):
        out.append((i, item))
    return out

def first_match(pattern, lines):
    for line in lines:
        if pattern in line:
            return line
    return None

def total_size(paths):
    size = 0
    for p in paths:
        size += os.path.getsize(p)
    return size

